{
  "technical_and_design_decisions": [
    "Build the EC2 AMI (U1) with Packer from an Ubuntu LTS base image, installing OpenJDK 17, Apache Kafka (with KRaft-mode ZooKeeper-less setup plus a ZooKeeper option for legacy XD compatibility), and standard performance tools (iostat, vmstat, JMX exporters); version the AMI with tags.",
    "Implement the load generator source (U2) and load receiving sink (U3) as Spring XD stream modules in Java on Spring Integration; the source exposes options for message size, producer rate, and total message count, and generates deterministic payload content.",
    "Implement the sink module (U3) with lock-free in-memory counters (AtomicLong) sampling received messages and bytes, emitting throughput (msgs/sec) to logs and XD metrics at a configurable interval.",
    "Run Windows CI (U4) on the existing Jenkins server using Windows Server EC2 agents spawned from custom AMIs; tag and isolate failing XD runtime tests via build profiles/exclusion lists so experiments with new AMI images do not break the main build.",
    "Fix Kafka source offset management (U5) by adding explicit per-partition offset control: support initial-offset module options and programmatic seek (via the Kafka consumer / message listener container) so fetches start from given offsets instead of only latest/earliest.",
    "Define the benchmark (U6) as a single-node simple stream (load-generator source -> load-receiving sink), run with fixed-duration windows, multiple repetitions, and varying message sizes/rates; record results in a report stored with the repo.",
    "Publish collateral (U7) as a Jekyll-based static site on the repository's gh-pages branch with sections for samples, tutorials, links, performance benchmarks, and reference architectures.",
    "Deliver the Lattice/Diego work (U8) as a proof-of-concept (not production code): a prototype deployer SPI implementation in the XD runtime that maps XD modules to Lattice/Diego LRPs, plus a written design proposal covering scope and risks."
  ],
  "assumptions": [
    "A single developer performs all work; all figures are work-hours of effort, not elapsed calendar time.",
    "An AWS account with permissions to launch instances and create/register AMIs is available; an existing Jenkins CI server and the Spring XD codebase/build system are already in place.",
    "A Kafka cluster for integration testing is available or is provisioned using the AMI created under U1; no commercial licensing costs or procurement effort is included.",
    "The gh-pages site requires no custom visual design or branding work beyond applying a standard Jekyll theme.",
    "The Lattice/Diego POC (U8) is time-boxed prototype-quality work; production hardening, security review, and merge into a release are out of scope.",
    "Effort includes unit and integration testing by the developer but excludes a separate formal QA cycle, code review by others, release management, and ongoing maintenance.",
    "Java 17 toolchain is available per the Spring Framework 6.0 baseline stated in the specification.",
    "No clarifications are needed from stakeholders; missing details are resolved by the decisions listed above."
  ],
  "activities": [
    {
      "activity_id": "A01",
      "activity_name": "AMI specification and package selection (U1)",
      "activity_description": "Define required packages and versions (JDK 17, Kafka, ZooKeeper/KRaft, monitoring/perf tools), select the base AMI, and specify the target instance configuration for running Kafka performance tests.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A02",
      "activity_name": "AMI provisioning scripts (U1)",
      "activity_description": "Author Packer template and shell provisioning scripts to install and configure all required packages, Kafka cluster defaults, and system tuning on the base image.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A03",
      "activity_name": "AMI build and validation (U1)",
      "activity_description": "Build the AMI, launch test instances, verify Kafka/ZooKeeper startup and basic perf-test readiness, fix provisioning defects, and tag the final AMI.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A04",
      "activity_name": "AMI usage documentation (U1)",
      "activity_description": "Document how to launch and use the AMI for Kafka performance tests (README/wiki), including credentials, ports, and cluster bootstrap steps.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A05",
      "activity_name": "Load generator source module design (U2)",
      "activity_description": "Design the source module: option schema (message size, rate, count), payload generation strategy, and integration points with the XD module model.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A06",
      "activity_name": "Load generator source module implementation (U2)",
      "activity_description": "Implement the Spring XD source module in Java (Spring Integration inbound channel adapter) with configurable throughput and payload generation.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A07",
      "activity_name": "Load generator source module tests (U2)",
      "activity_description": "Write unit tests for the generator logic and integration tests deploying the module in a local XD runtime stream.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A08",
      "activity_name": "Load receiving sink module design (U3)",
      "activity_description": "Design the sink module: counting/sampling approach, throughput calculation window, metrics emission, and module options.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A09",
      "activity_name": "Load receiving sink module implementation (U3)",
      "activity_description": "Implement the Spring XD sink module in Java that counts received messages/bytes and reports received throughput to logs and XD metrics.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A10",
      "activity_name": "Load receiving sink module tests (U3)",
      "activity_description": "Write unit tests for counting/throughput logic and integration tests validating measurement accuracy in an XD stream.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A11",
      "activity_name": "Windows CI infrastructure provisioning (U4)",
      "activity_description": "Create/prepare Windows Server AMIs with JDK 17 and build prerequisites, and register Windows build agents with the CI server.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A12",
      "activity_name": "Windows CI build job configuration (U4)",
      "activity_description": "Configure scheduled CI jobs that build XD and run runtime feature/functionality tests on the Windows agents.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A13",
      "activity_name": "Windows test failure triage and AMI experiments (U4)",
      "activity_description": "Run builds, isolate and categorize remaining test failures, and iterate with adjusted/new AMI images until a stable Windows test infrastructure is established.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A14",
      "activity_name": "Windows CI documentation (U4)",
      "activity_description": "Document the Windows CI setup, known isolated failures, and how to reproduce or extend the AMI images.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A15",
      "activity_name": "Kafka offset management analysis and reproduction (U5)",
      "activity_description": "Analyze the current Kafka source module offset handling, reproduce the inefficient fetch behavior, and define the expected offset-fetch semantics.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A16",
      "activity_name": "Kafka offset management fix implementation (U5)",
      "activity_description": "Implement explicit offset management in the Kafka source module so fetch operations start from the given offsets (per-partition seek and initial-offset options).",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A17",
      "activity_name": "Kafka offset management regression tests (U5)",
      "activity_description": "Add unit and integration tests (against a Kafka cluster) covering fetch-from-given-offset scenarios and edge cases such as out-of-range offsets and restarts.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A18",
      "activity_name": "Performance benchmark plan definition (U6)",
      "activity_description": "Define the benchmark methodology for a simple stream: stream topology, message sizes/rates, run duration, repetitions, and metrics to capture.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A19",
      "activity_name": "Simple stream benchmark execution (U6)",
      "activity_description": "Set up the environment (using the U1 AMI where applicable), deploy the simple stream with the U2/U3 modules, and execute the benchmark runs collecting throughput data.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A20",
      "activity_name": "Benchmark analysis and performance report (U6)",
      "activity_description": "Analyze the collected measurements, characterize overall throughput, and write the performance report for inclusion in project collateral.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A21",
      "activity_name": "gh-pages site structure and Jekyll setup (U7)",
      "activity_description": "Set up the Jekyll-based static site on the gh-pages branch, define navigation and page structure for samples, tutorials, links, performance benchmarks, and reference architectures.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A22",
      "activity_name": "gh-pages collateral authoring (U7)",
      "activity_description": "Author and organize the content: getting-started material, samples, tutorials, curated links, benchmark results (from U6), and reference architecture pages.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A23",
      "activity_name": "gh-pages review and deployment (U7)",
      "activity_description": "Proofread, fix links/formatting, and publish the site on GitHub Pages; verify rendering and navigation.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A24",
      "activity_name": "Lattice/Diego research spike (U8)",
      "activity_description": "Research Lattice and Diego APIs and deployment models; spike minimal deployments to understand how XD modules could map to LRPs/tasks.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A25",
      "activity_name": "Pluggable SPI POC implementation (U8)",
      "activity_description": "Implement the proof-of-concept pluggable SPI in the XD runtime with a prototype Lattice/Diego deployer, sufficient to deploy a simple module and evaluate feasibility.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A26",
      "activity_name": "POC findings and SPI design documentation (U8)",
      "activity_description": "Write up POC results: identified scope, risks, open questions, and the proposed overall design for a pluggable deployer SPI in the XD runtime.",
      "most_likely_effort": 12
    }
  ],
  "reported_total": {
    "most_likely_effort": 346
  }
}

